exercises.solution:
#include <stdio.h>
#include <string.h>

struct Person { char name[16]; };
static void set_name(struct Person *p, const char *n) {
    snprintf(p->name, sizeof p->name, "%s", n);
}

int main(void) {
    struct Person p;
    set_name(&p, "Charlie");
    puts(p.name);
    return 0;
}

