exercises.solution:
#include <stdio.h>

int main(void) {
    struct Counter { int value; };
    struct Counter increment(struct Counter c) { c.value++; return c; }
    struct Counter c = {5};
    printf("{%d}\n", increment(c).value);
    return 0;
}

